{
  "name": "@leo.gimp/opencode-usage-bar",
  "version": "3.0.1",
  "description": "OpenCode Go subscription usage bars for the opencode v2 TUI - 5h/weekly/monthly windows, /limit popup",
  "type": "module",
  "main": "./src/tui.tsx",
  "exports": {
    ".": "./src/tui.tsx",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "scripts",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "install-plugin": "node scripts/install.mjs"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.10"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "keywords": [
    "opencode",
    "opencode-go",
    "usage",
    "tui",
    "plugin"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Leogimp/opencode-usage-bar.git"
  },
  "bugs": {
    "url": "https://github.com/Leogimp/opencode-usage-bar/issues"
  },
  "homepage": "https://github.com/Leogimp/opencode-usage-bar#readme",
  "publishConfig": {
    "access": "public"
  },
  "license": "MIT"
}
